data.query:
query Query($where: KanbanRackWhereInput, $orderBy: [KanbanRackOrderByInput!], $first: Int, $after: String) {
  kanbanRack(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        rackNumber
         fromProductStrategyProcess {
          workcenterId
          assemblyBoms {
              edges {
                node {
                  id
                  componentProductId,
                  componentProductStrategyId,
                  componentProductStrategyProcessId,
                  assemblyProductStrategyProcessId,
                  standardUsage,
                  actualUsage,
                  consumptionModeId,
                  minimumUsage,
                  maximumUsage,
                  reference
        }
      }
    }
          workcenter {
            productionSetups {
              edges {
                node {
                  id
                }
              }
            }
          }
        }
        fromProductStrategyProcessId
        productId


        kanbanCards (orderBy: {field: cardNumber, direction: desc}, first: 1, where: {kanbanCardStatusId: {_eq: "Available" }}) {
          edges {
            node {
              id
            }
          }
        }
      }
    }
  }
}

data.variablesTransform:
{
  "payload":  [$state.context.kanbanRack.fromProductStrategyProcess.assemblyBoms.edges.node.({     
    "create": {
      "id":%.%.%.%.fromProductStrategyProcess.id & "-" & componentProductId,
      "order": order,
      "productionSetupOutputId": $state.context.productionSetupOutput.id,
      "componentProductId": componentProductId,
      "componentProductStrategyId":componentProductStrategyId,
      "componentProductStrategyProcessId":componentProductStrategyProcessId,
      "assemblyProductStrategyProcessId": assemblyProductStrategyProcessId,
       "productStrategyProcessBomId": id,
      "standardUsage": 0.2,
      "actualUsage": actualUsage,
      "consumptionModeId": consumptionModeId,
      "minimumUsage": minimumUsage,
      "maximumUsage":maximumUsage,
      "reference": reference
    }
  })]
}

(
  $dist := $state.context.workOrderProcessDistribution;
  $workcenter := $dist.workcenter;
  $shift := $executeTransform("getShift",{ "date":$state.context.productionSetupOutput.startAt});
{

  "payloadDistribution": {
    "where": {
      "id": $dist.id
    },
    "update": {
      "workOrderProcessDistributionStatusId": "Started",
      "actualStartAt": $state.context.productionSetupOutput.startAt
    }
  },
  "payloadHistory": {
    "create": {
      "transactionTypeId":  "Production Setup Add",
      "shiftId": $shift.id,
      "workcenterId": $workcenter.id,
      "occurAt": $state.context.productionSetupOutput.startAt,
      "eventId": null,
      "message": "Production Setup Output: " & $state.context.productionSetupOutput.id & " and Work Order Distribution: " &  $state.context.workOrderProcessDistribution.id & " Added"
    }
  },
  "payloadProcessStatus": {
    "where": {
      "id": $dist.workOrderProcess.id
    },
    "update": {
      "workOrderProcessStatusId": "Started"
    }
  }
}
)

